from .ute_syslog_entry import UteSyslogEntry
from .syslog_reader import SyslogReader


class UteSyslogReader(SyslogReader):
    cls = UteSyslogEntry

    btslog_seq_nr_parse_pattern_string = br"(?:(?P<btslog_seq_nr>\d{6}) )?"
    btslog_seq_nr_split_pattern_string = br"(?:\d{6} )?"
    btslog_timestamp_parse_pattern_string = br"(?P<btslog_timestamp>\d+\.\d+ \d+:\d+:\d+\.\d+) "
    btslog_timestamp_split_pattern_string = br"\d+\.\d+ \d+:\d+:\d+\.\d+ "
    source_ip_addr_parse_pattern_string = br"\[(?P<source_ip_addr>\d+\.\d+\.\d+\.\d+)\] "
    source_ip_addr_split_pattern_string = br"\[\d+\.\d+\.\d+\.\d+\] "

    _tool_prefix_parse_pattern_string = (
        btslog_seq_nr_parse_pattern_string
        + btslog_timestamp_parse_pattern_string
        + source_ip_addr_parse_pattern_string)

    _tool_prefix_split_pattern_string = (
        btslog_seq_nr_split_pattern_string
        + btslog_timestamp_split_pattern_string
        + source_ip_addr_split_pattern_string)
